// 编译期检查每列单调，防止后续手工更新破坏二分查询。
static constexpr bool vein_quantiles_valid() {
	for(int column = 0; column < 28; ++column) {
		for(int row = 1; row < 100; ++row) {
			if(vein_ratio_quantiles[row][column] < vein_ratio_quantiles[row - 1][column])
				return false;
		}
	}
	return true;
}
static_assert(vein_quantiles_valid());

double get_vein_exceed_probability(EVeinType vein_type, VeinMetric metric, double ratio) {
	if(vein_type <= None_vein || vein_type >= Max ||
		(metric != VeinMetric::Point && metric != VeinMetric::Amount) || std::isnan(ratio))
		throw std::invalid_argument("Invalid vein probability input");
	if(ratio < 0.0)
		return 1.0;
	const int column = (static_cast<int>(vein_type) - 1) * 2 + (metric == VeinMetric::Amount ? 1 : 0);
	// 查找第一个严格大于阈值的分位点；相同比例取最右分位，保留严格大于语义。
	int begin = 0;
	int end = 100;
	while(begin < end) {
		const int middle = begin + (end - begin) / 2;
		if(static_cast<double>(vein_ratio_quantiles[middle][column]) / 1000000.0 <= ratio)
			begin = middle + 1;
		else
			end = middle;
	}
	if(begin == 100)
		return 0.0;

	// 原表没有 0% 分位，采用 (0,0) 作为低端插值锚点。
	const double lower_ratio = begin == 0 ? 0.0 :
		static_cast<double>(vein_ratio_quantiles[begin - 1][column]) / 1000000.0;
	const double upper_ratio = static_cast<double>(vein_ratio_quantiles[begin][column]) / 1000000.0;
	const double fraction = (ratio - lower_ratio) / (upper_ratio - lower_ratio);
	return 1.0 - (static_cast<double>(begin) + fraction) / 100.0;
}
